#!/usr/bin/env bash
# smia-menu-label: 󱔢  Defaults
# smia-menu-order: 60
# smia-menu-managed: true

set -euo pipefail

XDG_CONFIG_HOME="${XDG_CONFIG_HOME:-$HOME/.config}"
TERMINALS_LIST="$XDG_CONFIG_HOME/xdg-terminals.list"
MENU_COMMAND="${SMIA_MENU_COMMAND:-smia-menu}"
BACK_STATUS="${SMIA_MENU_BACK_STATUS:-10}"
DESKTOP_DIRS=(
    "$HOME/.local/share/applications"
    "$HOME/.local/share/flatpak/exports/share/applications"
    /var/lib/flatpak/exports/share/applications
    /usr/local/share/applications
    /usr/share/applications
)

desktop_field() {
    awk -v key="$2" '
        /^\[/ { in_default = ($0 == "[Desktop Entry]") }
        in_default && $0 ~ "^"key"=" {
            sub("^"key"=", "")
            print
            exit
        }
    ' "$1"
}

# Print the Exec command only when it is a single word after stripping
# field codes; wrapper entries (flatpak, env) have no valid single-binary
# form for TERMINAL/EDITOR, so callers skip the env var for them.
desktop_exec() {
    local exec first rest
    exec="$(desktop_field "$1" Exec)"
    exec="${exec//%[fFuUdDnNickvm]/}"
    read -r first rest <<<"$exec"
    [[ -n "$first" && -z "$rest" ]] || return 1
    printf '%s' "$first"
}

write_defaults_env() {
    local env_dir="$XDG_CONFIG_HOME/environment.d"
    mkdir -p "$env_dir"
    local file="$env_dir/gnist-defaults.conf"
    local editor="" terminal="" key value
    if [[ -r "$file" ]]; then
        while IFS='=' read -r key value; do
            case "$key" in
                EDITOR) editor="$value" ;;
                VISUAL) [[ -n "$editor" ]] || editor="$value" ;;
                TERMINAL) terminal="$value" ;;
            esac
        done < "$file"
    fi
    [[ -n "${1:-}" ]] && editor="$1"
    [[ -n "${2:-}" ]] && terminal="$2"
    {
        printf '# Generated by smia-menu; do not edit manually.\n'
        if [[ -n "$editor" ]]; then printf 'EDITOR=%s\nVISUAL=%s\n' "$editor" "$editor"; fi
        if [[ -n "$terminal" ]]; then printf 'TERMINAL=%s\n' "$terminal"; fi
    } > "$file"
    if [[ -n "${1:-}" ]]; then
        systemctl --user set-environment "EDITOR=$1" "VISUAL=$1" 2>/dev/null || true
    fi
    if [[ -n "${2:-}" ]]; then
        systemctl --user set-environment "TERMINAL=$2" 2>/dev/null || true
    fi
}

list_desktops() {
    local pattern="$1" seen="" dir file base name
    for dir in "${DESKTOP_DIRS[@]}"; do
        [[ -d "$dir" ]] || continue
        for file in "$dir"/*.desktop; do
            [[ -r "$file" ]] || continue
            base="$(basename "$file")"
            case ":$seen:" in *":$base:"*) continue ;; esac
            grep -qE "$pattern" "$file" || continue
            [[ "$(desktop_field "$file" Hidden)" == "true" ]] && continue
            [[ "$(desktop_field "$file" NoDisplay)" == "true" ]] && continue
            name="$(desktop_field "$file" Name)"
            [[ -z "$name" ]] && name="$base"
            printf '%s|%s|%s\n' "$name" "$base" "$file"
            seen="$seen:$base"
        done
    done | sort -f
}

choose_desktop() {
    local label="$1" pattern="$2" choices name entry
    choices="$(list_desktops "$pattern")"
    if [[ -z "$choices" ]]; then
        "$MENU_COMMAND" notify "smia-menu" "No candidates found for $label"
        return "$BACK_STATUS"
    fi
    name="$(printf '%s\n' "$choices" | cut -d'|' -f1 | "$MENU_COMMAND" pick "$label")" \
        || return $?
    [[ -n "$name" ]] || return "$BACK_STATUS"
    entry="$(printf '%s\n' "$choices" | awk -F'|' -v n="$name" '$1 == n { print $2 "|" $3; exit }')"
    [[ -n "$entry" ]] || return "$BACK_STATUS"
    printf '%s\n' "$entry"
}

set_terminal() {
    local choice file path cmd rc
    if choice="$(choose_desktop "Terminal" '^Categories=.*TerminalEmulator')"; then
        :
    else
        rc=$?
        ((rc == BACK_STATUS)) && return 0
        return "$rc"
    fi
    file="${choice%%|*}"
    path="${choice#*|}"
    mkdir -p "$(dirname "$TERMINALS_LIST")"
    printf '%s\n' "$file" > "$TERMINALS_LIST"
    cmd="$(desktop_exec "$path" 2>/dev/null || true)"
    [[ -n "$cmd" ]] && write_defaults_env "" "$cmd"
    "$MENU_COMMAND" notify "Default terminal" "$file"
}

set_browser() {
    local choice file mime rc
    if choice="$(choose_desktop "Browser" '^MimeType=.*x-scheme-handler/https')"; then
        :
    else
        rc=$?
        ((rc == BACK_STATUS)) && return 0
        return "$rc"
    fi
    file="${choice%%|*}"
    for mime in x-scheme-handler/http x-scheme-handler/https text/html application/xhtml+xml; do
        gio mime "$mime" "$file"
    done
    "$MENU_COMMAND" notify "Default browser" "$file"
}

set_file_manager() {
    local choice file rc
    if choice="$(choose_desktop "File Manager" '^MimeType=.*inode/directory')"; then
        :
    else
        rc=$?
        ((rc == BACK_STATUS)) && return 0
        return "$rc"
    fi
    file="${choice%%|*}"
    gio mime inode/directory "$file"
    "$MENU_COMMAND" notify "Default file manager" "$file"
}

set_editor() {
    local choice file path cmd rc
    if choice="$(choose_desktop "Editor" '^Categories=.*TextEditor')"; then
        :
    else
        rc=$?
        ((rc == BACK_STATUS)) && return 0
        return "$rc"
    fi
    file="${choice%%|*}"
    path="${choice#*|}"
    gio mime text/plain "$file"
    cmd="$(desktop_exec "$path" 2>/dev/null || true)"
    [[ -n "$cmd" ]] && write_defaults_env "$cmd" ""
    "$MENU_COMMAND" notify "Default editor" "$file"
}

while true; do
    choice="$(printf '%s\n' \
        "󰆍  Terminal" \
        "󰖟  Browser" \
        "󰉋  File Manager" \
        "󰏤  Editor" \
        | "$MENU_COMMAND" pick "Defaults")" || exit $?
    case "$choice" in
        *Terminal*)       set_terminal ;;
        *Browser*)        set_browser ;;
        *"File Manager"*) set_file_manager ;;
        *Editor*)         set_editor ;;
    esac
done
